func lookupTopNode(file *ast.File, name string) ast.Node {
	for _, decl := range file.Decls {
		switch d := decl.(type) {
		case *ast.GenDecl:
			for _, spec := range d.Specs {
				switch s := spec.(type) {
				case *ast.TypeSpec:
					if s.Name.Name == name {
						return s
					}
				case *ast.ValueSpec:
					for _, n := range s.Names {
						if n.Name == name {
							// Return the whole ValueSpec, not just the Ident.
							return s
						}
					}
				}
			}
		case *ast.FuncDecl:
			if d.Name.Name == name {
				return d
			}
		}
	}
	return nil
}

